import { Component, input, output } from '@angular/core';

@Component({
  selector: 'app-stepper',
  template: `
    <button (click)="change(-1)">−</button>
    <span>{{ count() }}</span>
    <button (click)="change(1)">+</button>`
})
export class Stepper {
  count = input(0);
  countChange = output<number>();

  change(step: number) {
    this.countChange.emit(this.count() + step);
  }
}

